export function getHumanReadableTimeOffset(timezone: string): string | null {
  try {
    // Создаем объект даты с указанным часовым поясом
    const date = new Date();
    date.toLocaleString('en-US', { timeZone: timezone });

    // Получаем смещение в минутах
    const offsetMinutes = date.getTimezoneOffset();

    // Конвертируем в часы
    const offsetHours = offsetMinutes / 60;

    // Форматируем результат в удобочитаемый вид
    const sign = offsetHours >= 0 ? '+' : '-';
    const hours = Math.abs(offsetHours);
    const minutes = Math.abs(offsetMinutes % 60);

    return `${sign}${hours.toFixed(0).padStart(2, '0')}:${minutes.toFixed(0).padStart(2, '0')}`;
  } catch (error) {
    console.error(`Ошибка при получении смещения для часового пояса ${timezone}:`, error);
    return null;
  }
}

export function convertTimezone(
  date: Date,
  fromZone: string = Intl.DateTimeFormat().resolvedOptions().timeZone,
  toZone: string = Intl.DateTimeFormat().resolvedOptions().timeZone,
): Date {
  // Получаем UTC время
  const utc = date.toLocaleString('en-US', { timeZone: fromZone });
  const nd = new Date(Date.parse(utc)).toLocaleString('en-US', { timeZone: toZone });

  // Преобразуем в нужный часовой пояс
  return new Date(nd);
}

export const getGmtShift = (timezone: string) => {
  return new Date()
    .toLocaleTimeString(navigator.language, {
      timeZone: timezone,
      timeZoneName: 'short',
    })
    .split(' ')
    .pop();
};

