function getTimezoneOffset(
  timezone: string = Intl.DateTimeFormat().resolvedOptions().timeZone,
): number | null {
  try {
    // Создаем дату и форматируем её в указанной временной зоне
    const now = new Date();

    // Вариант 1: Используем toLocaleString с timeZone
    const dateString = now.toLocaleString('en-US', { timeZone: timezone, timeZoneName: 'short' });
    const tzAbbr = dateString.match(/\b[A-Z]{3,5}\b/)?.[0];
    if (!tzAbbr) return null;

    // Вариант 2: Более надежный способ - используем разницу между UTC и локальным временем
    const utcDate = new Date(now.toLocaleString('en-US', { timeZone: 'UTC' }));
    const tzDate = new Date(now.toLocaleString('en-US', { timeZone: timezone }));
    const offsetMilliseconds = tzDate.getTime() - utcDate.getTime();
    const offsetMinutes = Math.round(offsetMilliseconds / (1000 * 60));
    return offsetMinutes;
  } catch (e) {
    // В случае ошибки (например, неверное название временной зоны) возвращаем null
    console.warn(e);
    return null;
  }
}

// Функция для конвертации даты с учетом часового пояса
export function getLocalDateByTimezone(remoteDate: Date, timezone: string): Date {
  // Получаем смещение для указанного часового пояса
  const remoteOffset = (getTimezoneOffset(timezone) ?? 0) * -1;

  // Получаем локальное смещение
  const localOffset = remoteDate.getTimezoneOffset();

  // Вычисляем разницу между часовыми поясами
  const offsetDifference = (remoteOffset - localOffset) * 60 * 1000;

  // Создаем новую дату с учетом разницы
  const localDate = new Date(remoteDate.getTime() + offsetDifference);

  return localDate;
}
